# Create a shared helper to generate forward passes

forward_pass_helper = """
    def _generate_forward_pass(self, nodes: List[Node], edges: List[Edge], root: bool = False) -> List[str]:
        \"\"\"Generate branched topological forward pass.\"\"\"
        forward_lines = [
            "",
            f"{self.indent}def forward(self, x):",
        ]

        computational_nodes = [n for n in nodes if n.data.layerType.name not in ["Input", "Output", "Module"] or n.data.layerType.name == "Module"]

        if not computational_nodes:
            forward_lines.append(f"{self.indent}{self.indent}return x")
            return forward_lines

        try:
            from core.layer_builder import topological_sort
            execution_order = topological_sort(nodes, edges)

            # Identify input nodes
            input_nodes = [n.id for n in nodes if n.data.layerType.name == "Input"]

            var_map = {}
            for in_id in input_nodes:
                var_map[in_id] = "x"

            # Keep track of generated layer vars
            for node_id in execution_order:
                node = next((n for n in nodes if n.id == node_id), None)
                if not node:
                    continue

                layer_type = node.data.layerType.name
                if layer_type in ["Input", "Output"]:
                    continue

                # Find inputs
                incoming_edges = [e for e in edges if e.target == node_id]
                in_vars = []
                for e in incoming_edges:
                    if e.source in var_map:
                        in_vars.append(var_map[e.source])
                    else:
                        in_vars.append("x") # Fallback

                if not in_vars:
                    in_vars = ["x"]

                out_var = f"out_{self._node_id_to_layer_name(node_id)}"
                var_map[node_id] = out_var

                if layer_type.startswith("torch."):
                    op = layer_type.replace("torch.", "")
                    # Extract params
                    kwargs_strs = []
                    for k, v in node.data.parameters.items():
                        if v != "":
                            if isinstance(v, str) and not v.replace('.', '').replace('-', '').isdigit() and k != 'dim':
                                kwargs_strs.append(f"{k}='{v}'")
                            else:
                                if k == 'dim' and isinstance(v, str) and ',' in v:
                                    kwargs_strs.append(f"{k}=({v})")
                                else:
                                    kwargs_strs.append(f"{k}={v}")
                    kwarg_str = (", " + ", ".join(kwargs_strs)) if kwargs_strs else ""

                    if op in ["cat", "stack"]:
                        forward_lines.append(f"{self.indent}{self.indent}{out_var} = torch.{op}([{', '.join(in_vars)}]{kwarg_str})")
                    elif op in ["add", "sub", "mul", "div", "matmul", "bmm"]:
                        func_call = in_vars[0]
                        for inv in in_vars[1:]:
                            func_call = f"torch.{op}({func_call}, {inv})"
                        forward_lines.append(f"{self.indent}{self.indent}{out_var} = {func_call}")
                    else:
                        # Single input ops
                        forward_lines.append(f"{self.indent}{self.indent}{out_var} = torch.{op}({in_vars[0]}{kwarg_str})")
                else:
                    layer_name = self._node_id_to_layer_name(node_id)
                    if len(in_vars) == 1:
                        forward_lines.append(f"{self.indent}{self.indent}{out_var} = self.{layer_name}({in_vars[0]})")
                    else:
                        forward_lines.append(f"{self.indent}{self.indent}{out_var} = self.{layer_name}(*{', '.join(in_vars)})")

            # Determine return variable. Follow Output nodes or last computed
            output_nodes = [n.id for n in nodes if n.data.layerType.name == "Output"]
            if output_nodes:
                out_incoming = [e.source for e in edges if e.target in output_nodes]
                returns = [var_map[s] for s in out_incoming if s in var_map]
                if returns:
                    if len(returns) == 1:
                        forward_lines.append(f"{self.indent}{self.indent}return {returns[0]}")
                    else:
                        forward_lines.append(f"{self.indent}{self.indent}return {', '.join(returns)}")
                else:
                    forward_lines.append(f"{self.indent}{self.indent}return x")
            else:
                last_var = var_map.get(execution_order[-1], "x")
                forward_lines.append(f"{self.indent}{self.indent}return {last_var}")

        except Exception as e:
            forward_lines.append(f"{self.indent}{self.indent}# Error generating topology: {str(e)}")
            forward_lines.append(f"{self.indent}{self.indent}return x")

        return forward_lines
"""

